const MODERN_SITE_B64 = "";
  function b64DecodeUnicode(str) {
    return decodeURIComponent(atob(str).split('').map(function(c) {
      return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
    }).join(''));
  }
  let modernLoaded = false;
  function showWebTab(tab){
    document.querySelectorAll('.subtab').forEach(b=>b.classList.remove('active'));
    document.querySelectorAll('.subtab-panel').forEach(p=>p.classList.remove('active'));
    document.getElementById('web-tab-'+tab).classList.add('active');
    event.currentTarget.classList.add('active');
    if(tab === 'moderna' && !modernLoaded){
      document.getElementById('web-modern-frame').srcdoc = b64DecodeUnicode(MODERN_SITE_B64);
      modernLoaded = true;
    }
  }

/* ---- next inline script block ---- */

/* ---- Sparkles in hero ---- */
  (function(){
    const hero = document.getElementById('home-hero');
    if(!hero) return;
    const n = window.matchMedia('(max-width: 700px)').matches ? 10 : 20;
    for(let i=0;i<n;i++){
      const s = document.createElement('span');
      s.className = 'sparkle';
      s.style.left = (Math.random()*100) + '%';
      s.style.top = (30 + Math.random()*60) + '%';
      s.style.animationDuration = (4 + Math.random()*5) + 's';
      s.style.animationDelay = (Math.random()*6) + 's';
      hero.appendChild(s);
    }
  })();

  /* ---- Animated counters ---- */
  function animateCount(el){
    const target = parseInt(el.dataset.count, 10);
    const suffix = el.dataset.suffix || '';
    const dur = 1400;
    const start = performance.now();
    function step(now){
      const p = Math.min(1, (now - start) / dur);
      const eased = 1 - Math.pow(1 - p, 3);
      el.textContent = Math.round(target * eased) + suffix;
      if(p < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }
  const counterObserver = new IntersectionObserver((entries)=>{
    entries.forEach(e=>{
      if(e.isIntersecting){ animateCount(e.target); counterObserver.unobserve(e.target); }
    });
  }, {threshold:0.5});
  document.querySelectorAll('.hero-stat .num').forEach(el=>counterObserver.observe(el));

  /* ---- Staggered card reveal ---- */
  const cardObserver = new IntersectionObserver((entries)=>{
    entries.forEach((e, i)=>{
      if(e.isIntersecting){
        const idx = Array.from(document.querySelectorAll('.menu-card')).indexOf(e.target);
        e.target.style.transitionDelay = (idx * 60) + 'ms';
        e.target.classList.add('in');
        cardObserver.unobserve(e.target);
      }
    });
  }, {threshold:0.12});
  document.querySelectorAll('.menu-card').forEach(el=>cardObserver.observe(el));

  /* ---- Tilt / glow-follow on menu cards ---- */
  document.querySelectorAll('.menu-card').forEach(card=>{
    card.addEventListener('mousemove', (e)=>{
      const r = card.getBoundingClientRect();
      const mx = ((e.clientX - r.left) / r.width) * 100;
      const my = ((e.clientY - r.top) / r.height) * 100;
      card.style.setProperty('--mx', mx + '%');
      card.style.setProperty('--my', my + '%');
      const rx = ((my - 50) / 50) * -4;
      const ry = ((mx - 50) / 50) * 4;
      card.style.transform = `translateY(-4px) perspective(600px) rotateX(${rx}deg) rotateY(${ry}deg)`;
    });
    card.addEventListener('mouseleave', ()=>{
      card.style.transform = '';
    });
  });

  /* ---- Dynamic progress ring based on active cards ---- */
  (function(){
    const total = document.querySelectorAll('.menu-card').length;
    const active = document.querySelectorAll('.menu-card .status.active').length;
    const totalEl = document.getElementById('progress-total');
    const countEl = document.getElementById('progress-count');
    if(totalEl) totalEl.textContent = total;
    if(countEl) countEl.textContent = active;
    const ring = document.getElementById('progress-ring');
    if(ring){
      const c = 2 * Math.PI * 11;
      ring.style.strokeDasharray = c;
      ring.style.strokeDashoffset = c;
      requestAnimationFrame(()=>{
        setTimeout(()=>{ ring.style.strokeDashoffset = c * (1 - active/total); }, 300);
      });
    }
  })();